import random, time, sys
from functools import lru_cache
random.seed(210)

def count_ham_cycles(n, edges):
    out=[0]*n
    inm=[0]*n
    for u,v in edges:
        out[u] |= 1<<v
        inm[v] |= 1<<u
    FULL=((1<<n)-1) ^ 1  # vertices 2..n in 1-based terms
    @lru_cache(None)
    def f(mask,v):
        if mask == (1<<v):
            return 1 if (out[0]>>v)&1 else 0
