        m = inm[v] & prev
        while m:
            b = m & -m
            u = b.bit_length()-1
            total += f(prev, u)
            m -= b
        return total
    t=time.time()
    total=0
    for v in range(1,n):
        if out[v] & 1:
            total += f(FULL, v)
    dt=time.time()-t
