import random, math, sys
random.seed(301)

def det_bareiss(M):
    A=[row[:] for row in M]
    n=len(A)
    if n==0: return 1
    sign=1
    prev=1
    for k in range(n-1):
        if A[k][k]==0:
            for i in range(k+1,n):
                if A[i][k]!=0:
                    A[k],A[i]=A[i],A[k]
                    sign*=-1
                    break
            else:
                return 0
        pivot=A[k][k]
        for i in range(k+1,n):
            for j in range(k+1,n):
                A[i][j]=(A[i][j]*pivot - A[i][k]*A[k][j])//prev
        prev=pivot
        for i in range(k+1,n): A[i][k]=0
        for j in range(k+1,n): A[k][j]=0
    return sign*A[-1][-1]

def eulerian_count(n, edges, root=0):
    out=[0]*n; indeg=[0]*n
    for u,v in edges:
        out[u]+=1; indeg[v]+=1
    if out!=indeg: return None
    # count in-arborescences rooted at root via directed matrix tree theorem
    L=[[0]*n for _ in range(n)]
    for u,v in edges:
        L[v][v]+=1
        L[u][v]-=1
    M=[ [L[i][j] for j in range(n) if j!=root] for i in range(n) if i!=root ]
    t=det_bareiss(M)
    prod=1
    for d in out:
        prod*=math.factorial(d-1)
    return t*prod

