def det_mod(M,p):
    A=[[x%p for x in row] for row in M]
    n=len(A)
    det=1
    for i in range(n):
        pivot=None
        for r in range(i,n):
            if A[r][i]%p:
                pivot=r; break
        if pivot is None:
            return 0
        if pivot!=i:
            A[i],A[pivot]=A[pivot],A[i]
            det=(-det)%p
        det=(det*A[i][i])%p
        inv=pow(A[i][i],-1,p)
        for r in range(i+1,n):
            if A[r][i]%p:
                fac=A[r][i]*inv%p
                for c in range(i,n):
                    A[r][c]=(A[r][c]-fac*A[i][c])%p
    return det%p
for p in [101,1009,10007,1000003]:
